import React, { useEffect, useState } from 'react';
import api from '../services/api';
import { useAuth } from '../contexts/AuthContext';
import { FileText, Upload } from 'lucide-react';

export default function PlanoCurricular() {
  const { user } = useAuth();
  const isAdmin = user?.role === 'admin';
  const podePublicar = isAdmin || user?.role === 'coordenador' || (user?.curso_coordenado || user?.nivel_coordenado);
  const [planos, setPlanos] = useState([]);
  const [titulo, setTitulo] = useState('Plano curricular');
  const [arquivo, setArquivo] = useState(null);
  const [erro, setErro] = useState('');
  const [ok, setOk] = useState('');

  const carregar = () => api.get('/planos-curriculares').then(r => setPlanos(r.data)).catch(() => {});

  useEffect(() => { carregar(); }, []);

  const enviar = async (e) => {
    e.preventDefault();
    if (!arquivo) return setErro('Seleccione o ficheiro do plano (PDF, Word ou imagem).');
    const fd = new FormData();
    fd.append('arquivo', arquivo);
    fd.append('titulo', titulo);
    try {
      await api.post('/staff/plano-curricular', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      setOk('Plano publicado. Professores e alunos do seu âmbito podem consultá-lo.');
      setArquivo(null);
      carregar();
    } catch (err) {
      setErro(err.response?.data?.message || 'Erro ao publicar plano.');
    }
  };

  return (
    <div className="page-container">
      <div className="page-header">
        <h2><FileText size={22} style={{ verticalAlign: 'middle', marginRight: 8 }} />Plano curricular</h2>
        <p style={{ color: 'var(--cinza)' }}>
          {podePublicar
            ? 'Publique o plano para o ciclo ou curso que coordena. Professores e alunos recebem acesso no perfil.'
            : 'Consulte o plano curricular da sua área.'}
        </p>
      </div>
      {erro && <div className="alert alert-error">{erro}</div>}
      {ok && <div className="alert alert-success">{ok}</div>}
      {podePublicar && (
        <div className="card" style={{ marginBottom: '1.5rem' }}>
          <form onSubmit={enviar}>
            <div className="form-group">
              <label className="form-label">Título</label>
              <input className="form-control" value={titulo} onChange={e => setTitulo(e.target.value)} />
            </div>
            <div className="form-group">
              <label className="form-label">Ficheiro</label>
              <input type="file" className="form-control" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png" onChange={e => setArquivo(e.target.files?.[0] || null)} />
            </div>
            <button type="submit" className="btn btn-primary"><Upload size={16} /> Publicar plano</button>
          </form>
        </div>
      )}
      <div className="card" style={{ padding: 0 }}>
        <table className="table">
          <thead><tr><th>Título</th><th>Âmbito</th><th>Coordenador</th><th>Data</th></tr></thead>
          <tbody>
            {planos.map(p => (
              <tr key={p.id}>
                <td><strong>{p.titulo}</strong></td>
                <td>{p.curso_coordenado || p.nivel_coordenado || 'Geral'}</td>
                <td>{p.coordenador_nome}</td>
                <td>{new Date(p.criado_em).toLocaleDateString('pt-AO')}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
